// Emit only the public route type. Importing the Worker's source into the
// panel also imports incompatible DOM/workerd globals into svelte-check.
// This declaration is generated by TypeScript, never maintained as DTOs.
import ts from "typescript";
import {readFile,writeFile} from "node:fs/promises";
import {fileURLToPath} from "node:url";
const root=fileURLToPath(new URL("../",import.meta.url));
const config=ts.readConfigFile(`${root}worker/tsconfig.json`,ts.sys.readFile);
const parsed=ts.parseJsonConfigFileContent(config.config,ts.sys,`${root}worker`);
const program=ts.createProgram(parsed.fileNames,{...parsed.options,noEmit:false,declaration:true,emitDeclarationOnly:true});
const errors=[...program.getOptionsDiagnostics(),...program.getSyntacticDiagnostics(),...program.getSemanticDiagnostics()].filter(d=>d.category===ts.DiagnosticCategory.Error);
if(errors.length)throw new Error(ts.formatDiagnosticsWithColorAndContext(errors,{getCurrentDirectory:()=>root,getCanonicalFileName:n=>n,getNewLine:()=>"\n"}));
const source=program.getSourceFile(`${root}worker/index.ts`);
if(!source)throw new Error("Missing RPC entry");
let declaration="";
const result=program.emit(source,(_name,text)=>{declaration=text;},undefined,true);
if(result.emitSkipped||result.diagnostics.length)throw new Error("RPC declaration emit failed");
const ast=ts.createSourceFile("rpc.d.ts",declaration,ts.ScriptTarget.Latest,true);
const routes=ast.statements.filter(ts.isVariableStatement).flatMap(s=>s.declarationList.declarations).find(d=>d.name.getText(ast)==="routes");
if(!routes?.type)throw new Error("Missing RPC routes");
const wire=routes.type.getText(ast).replace(/HonoBase<App,/,"HonoBase<{},");
if(/Cloudflare|\bSession\b|\bApp\b|import\("\.\//.test(wire))throw new Error("Runtime-only type leaked into RPC");
const output="// Generated by worker/export-rpc.mjs from worker/index.ts AppType.\n// Do not edit. Contains wire types only, no Worker globals.\nexport type AppType = "+wire+";\n";
const target=`${root}src/lib/rpc.d.ts`;
if(await readFile(target,"utf8").catch(()=>"")!==output)await writeFile(target,output);
